// One item per article to fetch; the HTTP node runs once per item.
const ARTICLES_PER_RUN = 10;
return Array.from({ length: ARTICLES_PER_RUN }, (_, i) => ({ json: { i } }));

// Keep articles long enough for an IELTS-style reading passage; drop stubs.
const MIN_WORDS = 300, MAX_WORDS = 1000;
const out = [];
for (const item of $input.all()) {
  const page = item.json.query?.pages?.[0];
  if (!page?.extract) continue;
  const cleaned = page.extract
    .replace(/\n=+ (References|Other websites|Related pages|Notes|Sources) =+[\s\S]*$/, '')
    .replace(/\n=+ (.+?) =+\n/g, '\n\n$1\n')
    .trim();
  // Long articles: keep whole paragraphs up to MAX_WORDS instead of dropping them.
  let body = '', word_count = 0;
  for (const para of cleaned.split(/\n{2,}/)) {
    const n = para.split(/\s+/).length;
    if (word_count && word_count + n > MAX_WORDS) break;
    body += (body ? '\n\n' : '') + para;
    word_count += n;
  }
  if (word_count < MIN_WORDS) continue;
  out.push({ json: {
    source: 'simplewiki',
    source_id: String(page.pageid),
    title: page.title,
    url: page.fullurl,
    license: 'CC BY-SA 4.0',
    body,
    word_count,
  }});
}
return out;

